WebLink.url:
if({!Opportunity.IM_Commit_to_Forecast__c}==1){
alert('Opportunity has already been added to forecast.');
}
else{
if(confirm("PLEASE ENSURE THAT YOUR FORECAST IS UP TO DATE.\n\nClick 'OK' to add the opportunity to forecast now.\n\nClick 'Cancel' to review and update Revenue Schedule and Net New Revenue Forecast.")){
window.location.href="/apex/OpportunityCommit?oppId={!Opportunity.Id}";
}
else{
var flag = {!User.Suppress_Custom_Help_Popups__c};
if(flag==0){
var url = "/apex/OpportunityCommitHelp?oppId={!Opportunity.Id}";
openIntegration(url , 'height=250,width=640,resizable=no,toolbar=no,status=no,menubar=no,scrollbars=1', 2)
}
}
}
